Design a hook that supports both controlled and uncontrolled modes.

**Requirements:**
1. Import `useCallback` and `useState` from `react`.
2. Define and export:
   ```ts
   type UseControllableStateOptions<T> = {
     value?: T;
     defaultValue: T;
     onChange?: (next: T) => void;
   };

   useControllableState<T>(opts: UseControllableStateOptions<T>): readonly [T, (next: T) => void];
   ```
3. If `opts.value` is defined, treat the hook as controlled -- return `opts.value` and call `onChange(next)` from the setter.
4. Otherwise, store an internal `useState(opts.defaultValue)`; setter updates local state AND calls `onChange`.

This is the standard pattern behind controlled/uncontrolled inputs, dialogs, and disclosures.

files.content:
import { useCallback, useState } from 'react';

export type UseControllableStateOptions<T> = {
  value?: T;
  defaultValue: T;
  onChange?: (next: T) => void;
};

export function useControllableState<T>(
  opts: UseControllableStateOptions<T>,
): readonly [T, (next: T) => void] {
  const [internal, setInternal] = useState<T>(opts.defaultValue);
  const isControlled = opts.value !== undefined;
  const value = isControlled ? (opts.value as T) : internal;

  const setValue = useCallback(
    (next: T) => {
      if (!isControlled) {
        setInternal(next);
      }
      opts.onChange?.(next);
    },
    [isControlled, opts],
  );

  return [value, setValue] as const;
}
